197		if m.AgentName != "" && m.AgentName != string(agentName) {
198			// Marker was written for a different agent — leave it alone. The
199			// correct agent's session will reach its own hook and claim the
200			// marker.
201			return s, false, nil
202		}
203		// SHA drift: the marker was written for a specific commit. If HEAD has
204		// moved since, the user's intent (review THAT commit) no longer applies
205		// to this session, and we'd otherwise silently tag an unrelated session
206		// as a review. Discard the stale marker rather than adopting it or
207		// leaving it in place to mis-tag a later session.
