   408					_, err := runReviewConfigPicker(ctx, cmd.OutOrStdout())
   409					return err
   410				}
   411				return runReview(ctx, cmd, trackOnly, agentOverride)
   412			},
   413		}
   414		cmd.Flags().BoolVar(&edit, "edit", false, "re-open the review config picker")
   415		cmd.Flags().BoolVar(&trackOnly, "track-only", false, "write pending marker without spawning agent")
   416		cmd.Flags().StringVar(&agentOverride, "agent", "", "select a specific configured agent (default: alphabetically first)")
   417		cmd.AddCommand(newReviewAttachCmd())
   418		return cmd
   419	}
