   470	func runReview(ctx context.Context, cmd *cobra.Command, trackOnly bool, agentOverride string) error {
   471		out := cmd.OutOrStdout()
   472	
   473		// 1. Pre-flight: must be in a git repo.
   474		if _, err := paths.WorktreeRoot(ctx); err != nil {
   475			cmd.SilenceUsage = true
   476			fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Run `entire enable` first.")
   477			return NewSilentError(errors.New("not a git repository"))
   478		}
   479	
   480		// 2. Load config. A load error means the settings file exists but is
   481		// malformed (Load returns a default-filled object when the file is
   482		// missing). Surface the error instead of silently opening the picker,
   483		// which would cause saveReviewConfig to write over the user's other
   484		// settings with an empty EntireSettings{}.
   485		s, err := settings.Load(ctx)
   486		if err != nil {
   487			cmd.SilenceUsage = true
   488			fmt.Fprintf(cmd.ErrOrStderr(), "Failed to load settings: %v\n", err)
   489			fmt.Fprintln(cmd.ErrOrStderr(), "Fix `.entire/settings.json` and re-run `entire review`.")
   490			return NewSilentError(err)
   491		}
   492		if s == nil || len(s.Review) == 0 {
   493			picked, pickErr := runReviewConfigPicker(ctx, out)
   494			if pickErr != nil {
   495				return pickErr
   496			}
   497			if s == nil {
   498				s = &settings.EntireSettings{}
   499			}
   500			s.Review = picked
   501		}
   502	
   503		// 3. Pick agent.
   504		agentName, skills, err := selectReviewAgent(s.Review, agentOverride)
   505		if err != nil {
   506			cmd.SilenceUsage = true
   507			fmt.Fprintln(cmd.ErrOrStderr(), err.Error())
   508			return NewSilentError(err)
   509		}
   510	
   511		// 3.5. Verify hooks are installed for the selected agent. Without the
   512		// agent's lifecycle hooks firing, UserPromptSubmit will never adopt the
   513		// pending marker and the review metadata will never be recorded — a
   514		// silent failure mode. Stale config (e.g. user ran `entire disable`
   515		// without removing the agent from review settings) hits this same path.
   516		if !slices.Contains(GetAgentsWithHooksInstalled(ctx), types.AgentName(agentName)) {
   517			cmd.SilenceUsage = true
   518			fmt.Fprintf(cmd.ErrOrStderr(),
   519				"Hooks are not installed for %q. Run `entire configure --agent %s` first, "+
   520					"or remove %q from review settings.\n",
   521				agentName, agentName, agentName)
   522			return NewSilentError(fmt.Errorf("hooks not installed for %s", agentName))
   523		}
   524	
   525		// 4. Re-run guard: check if HEAD's checkpoint already has a review.
   526		if reviewed, meta := headHasReviewCheckpoint(ctx); reviewed {
   527			var proceed bool
   528			form := NewAccessibleForm(huh.NewGroup(
   529				huh.NewConfirm().
   530					Title(fmt.Sprintf("Already reviewed: %s. Proceed anyway?", meta)).
   531					Value(&proceed),
   532			))
   533			if err := form.Run(); err != nil {
   534				fmt.Fprintln(out, "prompt cancelled")
   535				return err //nolint:wrapcheck // propagate huh cancellation
   536			}
   537			if !proceed {
   538				fmt.Fprintln(out, "Review cancelled.")
   539				return nil
   540			}
   541		}
   542	
   543		// 5. Resolve HEAD + worktree root for the pending marker. WorktreePath
   544		// scopes the marker so that a session in *another* worktree sharing the
   545		// same .git/ can't race to claim it.
   546		headSHA, err := currentHeadSHA(ctx)
   547		if err != nil {
   548			return fmt.Errorf("resolve HEAD: %w", err)
   549		}
   550		worktreeRoot, err := paths.WorktreeRoot(ctx)
   551		if err != nil {
   552			return fmt.Errorf("resolve worktree root: %w", err)
   553		}
   554	
   555		// 6. Compose the review prompt once, then write the pending marker. The
   556		// composed prompt is carried on the marker so adoption records exactly
   557		// what the agent was asked to do (the same string passed to LaunchCmd
   558		// below), rather than recomposing from skills on the hook side.
   559		prompt := composeReviewPrompt(skills)
   560		if err := WritePendingReviewMarker(ctx, PendingReviewMarker{
   561			AgentName:    agentName,
   562			Skills:       skills,
   563			Prompt:       prompt,
   564			StartingSHA:  headSHA,
   565			StartedAt:    time.Now().UTC(),
   566			WorktreePath: worktreeRoot,
   567		}); err != nil {
   568			return fmt.Errorf("write pending marker: %w", err)
   569		}
   570	
   571		if trackOnly {
   572			// Marker must persist — the user will start the agent manually and
   573			// its hook will adopt the marker.
   574			fmt.Fprintln(out, "Pending review marker written.")
   575			fmt.Fprintf(out, "Start %s and run these skills manually: %s\n", agentName, strings.Join(skills, ", "))
   576			return nil
   577		}
   578	
   579		// 7. Resolve launcher BEFORE installing the cleanup defer. Non-launchable
   580		// agents fall back to the same persist-marker behavior as --track-only:
   581		// the user starts the agent manually and its UserPromptSubmit hook adopts
   582		// the marker. If we registered the defer first, it would wipe the marker
   583		// on this return path, silently breaking the fallback the message
   584		// promises the user.
   585		launcher, ok := agent.LauncherFor(types.AgentName(agentName))
   586		if !ok {
   587			fmt.Fprintf(out, "%s does not support subprocess launch yet. Falling back to --track-only.\n", agentName)
   588			fmt.Fprintf(out, "Start %s manually and run: %s\n", agentName, strings.Join(skills, ", "))
   589			return nil
   590		}
   591	
   592		// From this point on, the marker lives on disk until either (a) the
   593		// spawned agent's hook adopts and clears it, or (b) we clear it here
   594		// as a fallback. The defer covers every spawn/launch/run failure path,
   595		// and also the case where the agent exits cleanly without ever firing
   596		// UserPromptSubmit (e.g. user `/quit`s immediately). Leaving the marker
   597		// in those cases would mis-tag the next unrelated session as a review.
   598		defer func() {
   599			_, exists, readErr := ReadPendingReviewMarker(ctx)
   600			if readErr != nil || !exists {
   601				return
   602			}
   603			if clearErr := ClearPendingReviewMarker(ctx); clearErr != nil {
   604				logging.Debug(ctx, "cleanup unadopted review marker", slog.String("error", clearErr.Error()))
   605			}
   606		}()
   607		// Best-effort: show the user what's in scope so they can tell whether
   608		// the review target is what they expected. Failures are silent — scope
   609		// is informational, not load-bearing.
   610		if scope, scopeErr := detectReviewScope(ctx); scopeErr == nil {
   611			fmt.Fprintln(out, formatReviewScope(scope))
   612		}
   613		execCmd, err := launcher.LaunchCmd(ctx, prompt)
   614		if err != nil {
   615			return fmt.Errorf("launch %s: %w", agentName, err)
   616		}
   617		if err := execCmd.Run(); err != nil {
   618			return fmt.Errorf("agent exited: %w", err)
   619		}
   620		return nil
   621	}
   622	
   623	// selectReviewAgent picks an agent from the configured review map.
   624	//
   625	// If override is non-empty, returns the skills for that agent or an error
   626	// listing the configured alternatives. Otherwise returns the alphabetically
   627	// first configured agent — deterministic but user-overridable via --agent.
   628	func selectReviewAgent(review map[string][]string, override string) (string, []string, error) {
   629		if len(review) == 0 {
   630			return "", nil, errors.New("no review skills configured")
   631		}
   632		var names []string
   633		for name, skills := range review {
   634			if len(skills) > 0 {
   635				names = append(names, name)
   636			}
   637		}
   638		if len(names) == 0 {
   639			return "", nil, errors.New("no review skills configured")
   640		}
   641		sort.Strings(names)
   642		if override != "" {
   643			if skills, ok := review[override]; ok && len(skills) > 0 {
   644				return override, skills, nil
   645			}
   646			return "", nil, fmt.Errorf(
   647				"agent %q is not configured for review; configured agents: %s",
   648				override, strings.Join(names, ", "),
   649			)
   650		}
   651		pick := names[0]
   652		return pick, review[pick], nil
   653	}
   654	
   655	// composeReviewPrompt builds the initial prompt the agent receives.
   656	func composeReviewPrompt(skills []string) string {
   657		var sb strings.Builder
   658		sb.WriteString("Please run these review skills in order:\n")
   659		for i, skill := range skills {
   660			fmt.Fprintf(&sb, "  %d. %s\n", i+1, skill)
   661		}
   662		return sb.String()
   663	}
   664	
   665	// currentHeadSHA returns the current HEAD commit hash as a 40-char hex string.
   666	func currentHeadSHA(ctx context.Context) (string, error) {
   667		repoRoot, err := paths.WorktreeRoot(ctx)
   668		if err != nil {
   669			return "", fmt.Errorf("locate repo root: %w", err)
   670		}
   671		execCmd := exec.CommandContext(ctx, "git", "-C", repoRoot, "rev-parse", "HEAD")
   672		output, err := execCmd.Output()
   673		if err != nil {
   674			return "", fmt.Errorf("git rev-parse HEAD: %w", err)
   675		}
   676		return strings.TrimSpace(string(output)), nil
   677	}
   678	
   679	// reviewScope summarizes what's about to be reviewed, surfaced to the user
   680	// before the agent launches. Zero-valued fields mean "not detected" — format
   681	// helpers degrade gracefully.
   682	type reviewScope struct {
   683		Branch       string // current branch short name; "" if detached
   684		HeadSHA      string // short HEAD SHA (always set when non-empty scope)
   685		Base         string // base branch (e.g. "main"); "" if unknown
   686		AheadCommits int    // commits in base..HEAD; 0 if Base == ""
   687		FilesChanged int    // files in base..HEAD diff; 0 if Base == ""
   688		Uncommitted  int    // files from `git status --porcelain`
   689	}
   690	
   691	// detectReviewScope runs a handful of cheap `git` queries to describe the
   692	// set of changes the user is about to review. Best-effort: any individual
   693	// query that fails leaves the corresponding field at its zero value.
   694	func detectReviewScope(ctx context.Context) (reviewScope, error) {
   695		repoRoot, err := paths.WorktreeRoot(ctx)
   696		if err != nil {
   697			return reviewScope{}, fmt.Errorf("locate repo root: %w", err)
   698		}
   699		var s reviewScope
   700		s.Branch = gitString(ctx, repoRoot, "rev-parse", "--abbrev-ref", "HEAD")
   701		if s.Branch == detachedHEADDisplay {
   702			s.Branch = ""
   703		}
   704		s.HeadSHA = gitString(ctx, repoRoot, "rev-parse", "--short", "HEAD")
   705		s.Base = detectBaseBranch(ctx, repoRoot)
   706		if s.Base != "" && s.Branch != "" && s.Base != s.Branch {
   707			if n, ok := gitCount(ctx, repoRoot, "rev-list", "--count", s.Base+".."+s.Branch); ok {
   708				s.AheadCommits = n
   709			}
   710			if files := gitString(ctx, repoRoot, "diff", "--name-only", s.Base+"..."+s.Branch); files != "" {
   711				s.FilesChanged = len(strings.Split(files, "\n"))
   712			}
   713		}
   714		if status := gitString(ctx, repoRoot, "status", "--porcelain"); status != "" {
   715			s.Uncommitted = len(strings.Split(status, "\n"))
   716		}
   717		return s, nil
   718	}
   719	
   720	// detectBaseBranch resolves a base branch name by trying, in order:
   721	// origin/HEAD → origin/main → origin/master → local main → local master.
   722	// Returns "" if none match. Remote-tracking branches come first because they
   723	// reflect the team's convention; local branches are the fallback for repos
   724	// that haven't been `git fetch`'d recently.
   725	func detectBaseBranch(ctx context.Context, repoRoot string) string {
   726		if target := gitString(ctx, repoRoot, "symbolic-ref", "--short", "refs/remotes/origin/HEAD"); target != "" {
   727			return strings.TrimPrefix(target, "origin/")
   728		}
   729		candidates := []string{defaultBaseBranch, masterBaseBranch}
   730		for _, candidate := range candidates {
   731			if gitOK(ctx, repoRoot, "rev-parse", "--verify", "--quiet", "refs/remotes/origin/"+candidate) {
   732				return candidate
   733			}
   734		}
   735		for _, candidate := range candidates {
   736			if gitOK(ctx, repoRoot, "rev-parse", "--verify", "--quiet", "refs/heads/"+candidate) {
   737				return candidate
   738			}
   739		}
   740		return ""
   741	}
   742	
   743	// gitString runs `git -C repoRoot <args...>` and returns trimmed stdout, or
   744	// "" on any error.
   745	func gitString(ctx context.Context, repoRoot string, args ...string) string {
   746		full := append([]string{"-C", repoRoot}, args...)
   747		out, err := exec.CommandContext(ctx, "git", full...).Output()
   748		if err != nil {
   749			return ""
   750		}
   751		return strings.TrimSpace(string(out))
   752	}
   753	
   754	// gitOK runs `git -C repoRoot <args...>` and reports whether it succeeded.
   755	func gitOK(ctx context.Context, repoRoot string, args ...string) bool {
   756		full := append([]string{"-C", repoRoot}, args...)
   757		return exec.CommandContext(ctx, "git", full...).Run() == nil
   758	}
