   760	// gitCount runs a git command expected to output an integer and parses it.

Chunk ID: c50bd8
Wall time: 0.0000 seconds
Process exited with code 0
Original token count: 1230
Output:
   760	// gitCount runs a git command expected to output an integer and parses it.
   761	func gitCount(ctx context.Context, repoRoot string, args ...string) (int, bool) {
   762		s := gitString(ctx, repoRoot, args...)
   763		if s == "" {
   764			return 0, false
   765		}
   766		n, err := strconv.Atoi(s)
   767		if err != nil {
   768			return 0, false
   769		}
   770		return n, true
   771	}
   772	
   773	// formatReviewScope renders a one-line summary for the user. Empty-review
   774	// cases fall back to "no changes detected".
   775	func formatReviewScope(s reviewScope) string {
   776		head := s.Branch
   777		if head == "" {
   778			head = detachedHEADDisplay + " " + s.HeadSHA
   779		}
   780		var parts []string
   781		if s.Base != "" && s.Branch != "" && s.Base != s.Branch && (s.AheadCommits > 0 || s.FilesChanged > 0) {
   782			parts = append(parts,
   783				fmt.Sprintf("%d commits", s.AheadCommits),
   784				fmt.Sprintf("%d files changed", s.FilesChanged),
   785			)
   786		}
   787		if s.Uncommitted > 0 {
   788			parts = append(parts, fmt.Sprintf("%d uncommitted", s.Uncommitted))
   789		}
   790		suffix := "no changes detected"
   791		if len(parts) > 0 {
   792			suffix = strings.Join(parts, ", ")
   793		}
   794		if s.Base != "" && s.Branch != "" && s.Base != s.Branch {
   795			return fmt.Sprintf("Reviewing %s vs %s: %s", head, s.Base, suffix)
   796		}
   797		return fmt.Sprintf("Reviewing %s: %s", head, suffix)
   798	}
   799	
   800	// headHasReviewCheckpoint checks whether HEAD's checkpoint metadata includes
   801	// a review session. Returns (true, infoString) if HasReview is set.
   802	// Single lookup: read the Entire-Checkpoint trailer from HEAD, then resolve
   803	// the CheckpointSummary via ResolveCommittedReaderForCheckpoint so v2-enabled
   804	// repos also work (v1 alone would miss v2-written summaries).
   805	//
   806	// Each early return logs at Debug so users debugging "why is no review badge
   807	// showing?" have breadcrumbs without the caller having to ask for five
   808	// distinct failure modes.
   809	func headHasReviewCheckpoint(ctx context.Context) (bool, string) {
   810		repoRoot, err := paths.WorktreeRoot(ctx)
   811		if err != nil {
   812			logging.Debug(ctx, "head review check: locate worktree root", slog.String("error", err.Error()))
   813			return false, ""
   814		}
   815		execCmd := exec.CommandContext(ctx, "git", "-C", repoRoot, "log", "-1", "--format=%B")
   816		output, err := execCmd.Output()
   817		if err != nil {
   818			logging.Debug(ctx, "head review check: read HEAD commit message", slog.String("error", err.Error()))
   819			return false, ""
   820		}
   821		cpID, ok := trailers.ParseCheckpoint(string(output))
   822		if !ok {
   823			logging.Debug(ctx, "head review check: no Entire-Checkpoint trailer on HEAD")
   824			return false, ""
   825		}
   826		repo, err := git.PlainOpen(repoRoot)
   827		if err != nil {
   828			logging.Debug(ctx, "head review check: open repository", slog.String("error", err.Error()))
   829			return false, ""
   830		}
   831		v1Store := checkpoint.NewGitStore(repo)
   832		v2URL, urlErr := remote.FetchURL(ctx)
   833		if urlErr != nil {
   834			logging.Debug(ctx, "head review check: no configured v2 fetch remote", slog.String("error", urlErr.Error()))
   835			v2URL = ""
   836		}
   837		v2Store := checkpoint.NewV2GitStore(repo, v2URL)
   838		_, summary, err := checkpoint.ResolveCommittedReaderForCheckpoint(ctx, cpID, v1Store, v2Store, settings.IsCheckpointsV2Enabled(ctx))
   839		if err != nil || summary == nil {
   840			logging.Debug(ctx, "head review check: resolve checkpoint summary",
   841				slog.String("checkpoint_id", cpID.String()),
   842				slog.Any("error", err))
   843			return false, ""
   844		}
   845		if !summary.HasReview {
   846			logging.Debug(ctx, "head review check: summary HasReview is false", slog.String("checkpoint_id", cpID.String()))
   847			return false, ""
   848		}
   849		return true, fmt.Sprintf("checkpoint %s", cpID)
   850	}
   851	
   852	// saveReviewConfig persists the review map into .entire/settings.json while
   853	// preserving all other settings. A Load error means the file exists but is
   854	// malformed — we must NOT silently overwrite it with an empty struct, or
   855	// every unrelated setting the user had configured would be wiped. Return the
   856	// error so the caller can surface it instead.
   857	func saveReviewConfig(ctx context.Context, review map[string][]string) error {
   858		s, err := settings.Load(ctx)
   859		if err != nil {
   860			return fmt.Errorf("load settings before save: %w", err)
   861		}
   862		if s == nil {
   863			s = &settings.EntireSettings{}
   864		}
   865		s.Review = review
   866		if err := settings.Save(ctx, s); err != nil {
   867			return fmt.Errorf("save settings: %w", err)
   868		}
   869		return nil
   870	}

