432	func resolveAgent(existingState *session.State, agentName types.AgentName) (agent.Agent, error) {
433		if existingState != nil && existingState.AgentType != "" {
434			ag, err := agent.GetByAgentType(existingState.AgentType)
435			if err == nil {
436				return ag, nil
437			}
438			// Fall through to flag-based resolution.
439		}
