447	// resolveAndValidateTranscript finds the transcript file for a session, searching alternative
448	// project directories if needed.
449	func resolveAndValidateTranscript(ctx context.Context, sessionID string, ag agent.Agent) (string, error) {
450		transcriptPath, err := resolveTranscriptPath(ctx, sessionID, ag)
451		if err != nil {
452			return "", fmt.Errorf("failed to resolve transcript path: %w", err)
453		}
454		// Only call PrepareTranscript when the file already exists — it flushes
455		// in-progress writes, but can't conjure a file that was never started.
456		// This avoids agents like Cursor polling for 3s on non-existent files
457		// during auto-detection.
458		if _, statErr := os.Stat(transcriptPath); statErr == nil {
459			if preparer, ok := agent.AsTranscriptPreparer(ag); ok {
460				if prepErr := preparer.PrepareTranscript(ctx, transcriptPath); prepErr != nil {
461					logging.Debug(ctx, "PrepareTranscript failed (best-effort)", "error", prepErr)
462				}
463			}
464			return transcriptPath, nil
465		}

